package com.adaptivelearning.goalproject.domain;
import com.adaptivelearning.shared.exception.BusinessException;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;
class StateMachineTest {@Test void goalAllowsDocumentedTransitions(){assertThatCode(()->GoalStatus.DRAFT.requireCanTransitionTo(GoalStatus.ACTIVE)).doesNotThrowAnyException();assertThatThrownBy(()->GoalStatus.COMPLETED.requireCanTransitionTo(GoalStatus.PAUSED)).isInstanceOf(BusinessException.class);}@Test void projectSupportsEntireDocumentedLifecycle(){assertThatCode(()->ProjectStatus.DRAFT.requireCanTransitionTo(ProjectStatus.ACTIVE)).doesNotThrowAnyException();assertThatCode(()->ProjectStatus.ACTIVE.requireCanTransitionTo(ProjectStatus.PAUSED)).doesNotThrowAnyException();assertThatCode(()->ProjectStatus.PAUSED.requireCanTransitionTo(ProjectStatus.ACTIVE)).doesNotThrowAnyException();assertThatCode(()->ProjectStatus.ACTIVE.requireCanTransitionTo(ProjectStatus.COMPLETED)).doesNotThrowAnyException();assertThatCode(()->ProjectStatus.COMPLETED.requireCanTransitionTo(ProjectStatus.ARCHIVED)).doesNotThrowAnyException();assertThatCode(()->ProjectStatus.CANCELED.requireCanTransitionTo(ProjectStatus.ARCHIVED)).doesNotThrowAnyException();assertThatThrownBy(()->ProjectStatus.COMPLETED.requireCanTransitionTo(ProjectStatus.ACTIVE)).isInstanceOf(BusinessException.class);}@Test void pausedProjectCannotCompleteBecauseBusinessDesignOnlyAllowsResumeOrCancel(){assertThatThrownBy(()->ProjectStatus.PAUSED.requireCanTransitionTo(ProjectStatus.COMPLETED)).isInstanceOf(BusinessException.class);}}
